(function(){
 if(!document.body.classList.contains('shared-app')){const previous=renderReports;renderReports=function(){previous();if(manager())document.querySelector('#workspace').insertAdjacentHTML('beforeend','<details class="task-extra" style="margin-top:22px"><summary>گزارش کوتاه حضور در سایت</summary><p class="hint">این گزارش پس از ورود واقعی اعضا در فضای مشترک فعال است؛ انتخاب پنل آزمایشی، هویت فرد را مشخص نمی‌کند و حضور کارکنان را ثبت نمی‌کند.</p><a class="text-btn" href="shared.html">ورود به فضای مشترک</a></details>')};return;}
 let presenceId=crypto.randomUUID(),presenceProject=null,lastInput=Date.now(),previousActive=false,inflight=false,reportDay=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
 const dayKey=()=>{const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tehran',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return ['year','month','day'].map(k=>p.find(x=>x.type===k).value).join('-')};reportDay=dayKey();
 for(const event of ['pointerdown','keydown','scroll','pointermove','touchstart'])document.addEventListener(event,()=>lastInput=Date.now(),{passive:true});
 async function pulse(force){if(inflight)return;const pid=project?.id;if(!session||!mine()||!pid)return;inflight=true;try{if(presenceProject&&presenceProject!==pid){await rpc('sm_presence',{p_project:presenceProject,p_session:presenceId,p_event:'end'}).catch(()=>{});presenceId=crypto.randomUUID();previousActive=false}presenceProject=pid;const active=document.visibilityState==='visible'&&document.hasFocus()&&Date.now()-lastInput<120000;const event=force||(active?'beat':'pause');if(event==='pause'&&!previousActive)return;await rpc('sm_presence',{p_project:pid,p_session:presenceId,p_event:event});previousActive=event==='beat';if(event==='end'){presenceId=crypto.randomUUID();previousActive=false}}catch{}finally{inflight=false}}
 setInterval(()=>pulse(),30000);setTimeout(()=>pulse(),2000);document.addEventListener('visibilitychange',()=>pulse());window.addEventListener('focus',()=>{lastInput=Date.now();pulse()});window.addEventListener('blur',()=>pulse('pause'));window.addEventListener('pagehide',()=>pulse('end'));
 document.addEventListener('click',e=>{if(e.target.closest('#signout'))pulse('end')},true);
 const priorRender=render;render=function(){priorRender();if(session&&mine()){let notice=document.querySelector('#presenceDisclosure');if(!notice){notice=document.createElement('small');notice.id='presenceDisclosure';notice.style.cssText='display:block;font-size:9px;color:#98a7bc;margin-top:9px';notice.textContent='زمان حضور فعال در سایت برای گزارش مدیریت ثبت می‌شود.';document.querySelector('.desk-bottom')?.append(notice)}}};
 const priorReports=renderReports;renderReports=function(){priorReports();if(!management())return;const root=el('#sharedContent');root.insertAdjacentHTML('beforeend','<details id="presenceReport" class="shared-section"><summary>گزارش کوتاه حضور در سایت</summary><p class="shared-meta">حضور فعال سایت، جدا از ساعت کار ثبت‌شده است. تب پنهان یا بیش از دو دقیقه بی‌فعالیت محاسبه نمی‌شود. در قطع ناگهانی اتصال، آخرین مشاهده گزارش می‌شود.</p><label>روز گزارش<input type="date" id="presenceDay" value="'+reportDay+'"></label><div id="presenceRows"></div></details>');el('#presenceReport').ontoggle=()=>{if(el('#presenceReport').open)loadPresence()};el('#presenceDay').onchange=e=>{reportDay=e.target.value;if(reportDay)loadPresence()}};
 async function loadPresence(){const pid=project.id,day=reportDay,box=el('#presenceRows');box.textContent='در حال دریافت…';try{const rows=await rpc('sm_presence_report',{p_project:pid,p_day:day});if(!box.isConnected||project.id!==pid||reportDay!==day)return;const time=x=>x?new Date(x).toLocaleTimeString('fa-IR',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Tehran'}):'—';box.innerHTML=rows.length?'<div style="overflow:auto"><table style="width:100%;font-size:11px;text-align:right"><thead><tr><th>نام</th><th>اولین ورود</th><th>آخرین مشاهده</th><th>آخرین خروج ثبت‌شده</th><th>حضور فعال</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(person(r.member_id))+(r.online?' · آنلاین':'')+'</td><td>'+time(r.first_seen)+'</td><td>'+time(r.last_seen)+'</td><td>'+time(r.last_exit)+'</td><td>'+fa(Math.floor(Number(r.active_seconds)/3600))+' ساعت و '+fa(Math.floor(Number(r.active_seconds)%3600/60))+' دقیقه</td></tr>').join('')+'</tbody></table></div>':'<p class="shared-meta">برای این روز حضوری ثبت نشده است.</p>'}catch(e){box.textContent=failure(e)}}
})();
